def _parse_datetime(value: Any) -> datetime:
    text = str(value or "").strip()
    if not text:
        raise ValueError("timestamp is missing")
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        raise ValueError(f"timestamp has no timezone: {text}")
    return parsed.astimezone(timezone.utc)


def _decimal(value: Any) -> Decimal:
    try:
        return Decimal(str(value)).quantize(Decimal("0.01"))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError(f"invalid decimal value: {value!r}") from exc


def _value_exact(key: str, actual: Any, expected: Any) -> bool:
    if key in _MONEY_FIELDS:
        try:
            return _decimal(actual) == _decimal(expected)
        except ValueError:
            return False
    if isinstance(expected, bool):
        return actual is expected
    if isinstance(expected, Mapping):
        return isinstance(actual, Mapping) and _record_exact(actual, expected)
    if isinstance(expected, list):
        return isinstance(actual, list) and actual == expected
    return type(actual) is type(expected) and actual == expected


def _record_exact(actual: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    return set(actual) == set(expected) and all(
        _value_exact(key, actual.get(key), expected_value)
        for key, expected_value in expected.items()
    )


def _objects(state: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    value = state.get(key)
    if not isinstance(value, list):
        return []
    return [dict(item) for item in value if isinstance(item, Mapping)]


def _unique_where(
    items: Sequence[Mapping[str, Any]],
    predicate: Callable[[Mapping[str, Any]], bool],
) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    matches = [dict(item) for item in items if predicate(item)]
    return (matches[0] if len(matches) == 1 else None), matches


def _event_payload(event: Mapping[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in event.items() if key not in {"seq", "timestamp"}}


def _check(
    spec: Mapping[str, Any],
    passed: bool,
    *,
    actual: Any,
    evidence: Any,
    event_evidence: Any,
    failure_reason: str | None = None,
) -> dict[str, Any]:
    return {
        "name": spec["name"],
        "steps": list(spec["steps"]),
        "passed": bool(passed),
        "expected": spec["expected"],
        "actual": actual,
        "evidence": evidence,
        "event_evidence": event_evidence,
        "failure_reason": None if passed else (failure_reason or "exact checkpoint mismatch"),
    }


